const uid = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const token = () => Array.from(crypto.getRandomValues(new Uint32Array(3))).map(x => x.toString(36)).join("");
const escapeHtml = (value="") => String(value).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const t = (key) => text[state.language][key] || key;
const dateInput = (value) => value ? new Date(value).toLocaleDateString(state.language === "nb" ? "nb-NO" : "en-GB") : "—";
const isoDate = (date = new Date()) => date.toISOString().slice(0, 10);
function futureDate(days) { const date = new Date(); date.setDate(date.getDate() + days); return isoDate(date); }
function ensureReviews() { let changed=false; state.reviews ||= {}; reviewRoutines.forEach(routine => { if (!state.reviews[routine.id]) { state.reviews[routine.id]={ nextDate:futureDate(routine.days), lastReviewed:"" }; changed=true; } }); return changed; }
function reviewRoutine(routine) { return state.reviews[routine.id]; }
function isReviewDue(routine) { return reviewRoutine(routine).nextDate <= isoDate(); }

function openDb() { return new Promise((resolve, reject) => { const request = indexedDB.open(DB_NAME, DB_VERSION); request.onupgradeneeded = () => { const database=request.result; if (!database.objectStoreNames.contains("settings")) database.createObjectStore("settings"); }; request.onsuccess = () => { db = request.result; resolve(); }; request.onerror = () => reject(request.error); }); }
function loadState() { return new Promise((resolve, reject) => { const request = db.transaction("settings").objectStore("settings").get(STATE_KEY); request.onsuccess = () => { if (request.result) state = {...state, ...request.result, household:{...state.household, ...request.result.household}, emergencyPlan:{...state.emergencyPlan, ...request.result.emergencyPlan}, checklist:request.result.checklist || {}}; resolve(); }; request.onerror = () => reject(request.error); }); }
function persist() { return new Promise((resolve, reject) => { const request = db.transaction("settings", "readwrite").objectStore("settings").put(state, STATE_KEY); request.onsuccess = () => resolve(); request.onerror = () => reject(request.error); }); }
function toast(message) { const el = document.createElement("div"); el.className = "toast"; el.textContent = message; $("#toast-region").append(el); setTimeout(() => el.remove(), 2500); }
function route() { return location.hash.slice(1) || "dashboard"; }
function statusClass(percent) { return percent >= 100 ? "good" : percent >= 50 ? "warning" : "danger"; }
function waterLitres() { const registered=state.waterStores.reduce((sum, store) => sum + Number(store.litres || 0), 0); const legacy=state.inventory.filter(i => i.category === "water").reduce((sum, i) => sum + (i.unit === "L" ? Number(i.quantity) : 0), 0); return registered + legacy; }
function waterTarget() { return Number(state.household.people || 1) * 20; }
function applicableChecklist() { return dsbChecklist.filter(item => !item.when || state.household[item.when]); }
function checklistStatus(item) { if (item.inventoryTracked && waterLitres() >= waterTarget()) return "have"; return state.checklist?.[item.id] || ""; }
function checklistSummary() { const items=applicableChecklist(); const have=items.filter(item => checklistStatus(item) === "have").length; const need=items.filter(item => checklistStatus(item) === "need").length; return { total:items.length, have, need }; }
function categorySummary(category) { const items=applicableChecklist().filter(item => item.category === category); const complete=items.filter(item => ["have", "skip"].includes(checklistStatus(item))).length; const need=items.filter(item => checklistStatus(item) === "need").length; return { total:items.length, complete, need, percentage:items.length ? Math.round(complete / items.length * 100) : 0 }; }
function nextReadinessAction() {
  const current=waterLitres(), target=waterTarget(), missing=Math.max(0,target-current);
  if (missing > 0) return `<div class="callout"><strong>${missing} L ${t("water")}</strong><br>${state.language === "nb" ? "mangler for å nå målet for husstanden." : "needed to reach your household target."}<p class="callout-action"><a class="button small" href="#water">${state.language === "nb" ? "Administrer vann" : "Manage water"} →</a></p></div>`;
  for (const category of categories.filter(category => category !== "water")) {
    const items=applicableChecklist().filter(item => item.category === category);
    const incomplete=items.filter(item => !["have", "skip"].includes(checklistStatus(item)));
    if (incomplete.length) {
      const label=categoryNames[state.language][category];
      const detail=state.language === "nb" ? `${incomplete.length} ${incomplete.length === 1 ? "punkt" : "punkter"} er ikke avklart.` : `${incomplete.length} ${incomplete.length === 1 ? "item is" : "items are"} not addressed.`;
      return `<div class="callout"><strong>${label}</strong><br>${detail}<p><a href="#onboarding">${state.language === "nb" ? "Gå til sjekklisten" : "Open checklist"} →</a></p></div>`;
    }
  }
  const next=reviewRoutines.map(routine => ({ routine, review:reviewRoutine(routine) })).sort((a,b) => a.review.nextDate.localeCompare(b.review.nextDate))[0];
  return `<div class="callout"><strong>${state.language === "nb" ? "Alt er avklart" : "Everything is covered"}</strong><br>${next ? `${state.language === "nb" ? "Neste kontroll" : "Next review"}: ${state.language === "nb" ? next.routine.nb : next.routine.en} · ${dateInput(next.review.nextDate)}.` : ""}<p><a href="#reviews">${state.language === "nb" ? "Se kontrollrutinen" : "View review routine"} →</a></p></div>`;
}
function locationName(id) { return state.locations.find(l => l.id === id)?.name || t("none"); }
function locationTypeName(type) { return locationTypeNames[state.language][String(type || "").toLowerCase()] || type; }
function compactLocationName(name) { const letters=String(name || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^A-Za-z]/g, "").toUpperCase(); const withoutVowels=letters.replace(/[AEIOUY]/g, ""); return (withoutVowels.length >= 4 ? withoutVowels : letters).slice(0, 5).padEnd(4, "X"); }
function ancestorRoom(location) { let current=location; while (current) { if (String(current.type).toLowerCase() === "room") return current; current=state.locations.find(candidate => candidate.id === current.parentId); } return undefined; }
function locationBreadcrumb(location) { const trail=[]; let current=location; while(current) { trail.unshift(current); current=state.locations.find(candidate => candidate.id === current.parentId); } return `<nav class="location-breadcrumb" aria-label="${state.language === "nb" ? "Oppbevaringssted" : "Storage location"}">${trail.map((entry,index) => index === trail.length - 1 ? `<span aria-current="page">${escapeHtml(entry.name)}</span>` : `<a href="#locations?id=${entry.id}">${escapeHtml(entry.name)}</a>`).join(`<span class="breadcrumb-separator" aria-hidden="true">›</span>`)}</nav>`; }
function createLocationCode(type, name, parentId) { const normalizedType=String(type).toLowerCase(); const parent=state.locations.find(location => location.id === parentId); const room=parent && ancestorRoom(parent); const area=room ? compactLocationName(room.name) : compactLocationName(parent?.name || name); const first=parent ? area : (locationTypeCodes[normalizedType] || normalizedType.toUpperCase().slice(0,5)); const second=parent ? (locationTypeCodes[normalizedType] || normalizedType.toUpperCase().slice(0,5)) : area; const base=`${first}-${second}`; let sequence=1; while(state.locations.some(location => location.code === `${base}-${String(sequence).padStart(2,"0")}`)) sequence += 1; return `${base}-${String(sequence).padStart(2,"0")}`; }
function datedItems() { return state.inventory.filter(i => i.date).sort((a,b) => a.date.localeCompare(b.date)); }
function dueGroup(item) { const days = Math.ceil((new Date(`${item.date}T00:00:00`) - new Date()) / 86400000); if (days < 0) return "expired"; if (days <= 7) return "week"; if (days <= 31) return "month"; return "review"; }
function nav() { const currentRoute=route().split("?")[0]; const labels={ household:state.language === "nb" ? "Husstandsoppsett" : "Household setup", contacts:state.language === "nb" ? "Kontakter" : "Contacts", reviews:state.language === "nb" ? "Fast kontrollrutine" : "Review routine" }; document.querySelectorAll(".sidebar a").forEach(a => { a.classList.toggle("active", a.dataset.route === currentRoute); a.textContent = labels[a.dataset.route] || t(a.dataset.route === "dashboard" ? "overview" : a.dataset.route === "onboarding" ? "checklist" : a.dataset.route === "scenarios" ? "scenarios" : a.dataset.route === "inventory" ? "supplies" : a.dataset.route === "rotation" ? "useSoon" : a.dataset.route); }); }
function heading(title, eyebrow, actions="") { return `<div class="page-heading"><div><p class="eyebrow">${escapeHtml(eyebrow)}</p><h1>${escapeHtml(title)}</h1></div>${actions}</div>`; }
function peopleCounter(value, inputId) { return `<div class="counter-field full"><span class="counter-label">${t("people")}</span><div class="counter" role="group" aria-label="${t("people")}"><button type="button" class="counter-button" data-action="decrement-people" data-target="${inputId}" aria-label="${state.language === "nb" ? "Fjern én person" : "Remove one person"}">−</button><input id="${inputId}" name="people" type="number" min="1" value="${value}" aria-label="${t("people")}" readonly><button type="button" class="counter-button" data-action="increment-people" data-target="${inputId}" aria-label="${state.language === "nb" ? "Legg til én person" : "Add one person"}">+</button></div></div>`; }
function litresCounter(value=1) { const label=state.language === "nb" ? "Liter" : "Litres"; return `<div class="counter-field full"><span class="counter-label">${label}</span><div class="counter" role="group" aria-label="${label}"><button type="button" class="counter-button" data-action="decrement-water-litres" data-target="water-litres" aria-label="${state.language === "nb" ? "Fjern én liter" : "Remove one litre"}">−</button><input id="water-litres" name="litres" type="number" min="1" value="${value}" aria-label="${label}" readonly><button type="button" class="counter-button" data-action="increment-water-litres" data-target="water-litres" aria-label="${state.language === "nb" ? "Legg til én liter" : "Add one litre"}">+</button></div></div>`; }
